public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        PrintWriter outputWriter = new PrintWriter(System.out);
        InputReader reader = new InputReader(inputStream);
        performShufflingCalculation(reader, outputWriter);
        outputWriter.close();
    }

    static void performShufflingCalculation(InputReader in, PrintWriter out) {
        int totalCards = in.nextInt();
        int totalShuffles = in.nextInt();

        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        mod.fInv(totalCards + totalShuffles);

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = mod.mult(p, totalCards - i, mod.smallInv(totalShuffles + totalCards - i));
            phaseSize = mod.add(phaseSize, p);
        }

        long answer = 0;
        for (int k = 1; k <= totalCards; k++) {
            long sign = mod.paritySign(k + 1);
            long numPhases = mod.div(totalShuffles + k, k);
            long term = mod.mult(sign, mod.ncr(totalCards, k), numPhases, phaseSize);
            answer = mod.add(answer, term);
        }

        out.println(answer);
    }
}

class InputReader {
    BufferedReader br;
    StringTokenizer st;

    public InputReader(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
        st = null;
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}
