#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long inv[2001];

    long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long div(long long a, long long b) {
        return mult(a, inv[b]);
    }

    long long ncr(int n, int r) {
        if (r > n || r < 0) return 0;
        long long res = 1;
        for (int i = 1; i <= r; i++) {
            res = mult(res, n - i + 1);
            res = mult(res, inv[i]);
        }
        return res;
    }

    long long paritySign(int x) {
        return (x % 2 == 0) ? 1 : -1;
    }

    void fInv(int n) {
        inv[1] = 1;
        for (int i = 2; i <= n; i++) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }
    }

    long long smallInv(int n) {
        return inv[n];
    }

    long long mult(long long a, long long b, long long c = 1, long long d = 1) {
        long long res = mult(a, b);
        res = mult(res, c);
        res = mult(res, d);
        return res % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalCards, totalShuffles;
    cin >> totalCards >> totalShuffles;

    Mod998 mod;
    mod.fInv(totalCards + totalShuffles);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, totalCards - i, mod.smallInv(totalShuffles + totalCards - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= totalCards; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.div(totalShuffles + k, k);
        long long term = mod.mult(sign, mod.ncr(totalCards, k), numPhases, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";
    return 0;
}
